from lib import *
S = SS('x75')
steps = [
    step("先看 classpath。同一份 webmvc 应用,默认(spring-boot-starter-tomcat)的 classpath 共 39 个 jar、合计 18.7 MB,名字里带 tomcat 的 6 个,内嵌 Tomcat 是 tomcat-embed-core 11.0.24;换成 spring-boot-starter-jetty(并去掉 Tomcat 的 jar)共 77 个 jar、合计 19.9 MB,名字里带 jetty 的 33 个,Jetty 是 12.1.12,依赖里还带着 jetty-ee11-websocket、jetty-annotations、jetty-client 等一整套。Tomcat 和 Jetty 的 starter 同时放在 classpath 上会怎样:实际跑起来的是 Jetty——Bean 里是 jettyServletWebServerFactory,处理请求的线程叫 qtp…,不是 Tomcat 的 http-nio-…-exec-…(classpath 上依然能加载到 Tomcat 的类,所以只用「能不能加载到某个类」来判断运行的是谁会判断错)。Undertow:我去查了 Maven Central,spring-boot-starter-undertow 的最新版本停在 4.0.0-M1,4.0.8 的这个 pom 返回 404,Boot 4.0.8 里已经没有 Undertow 这个选项。", t=tl(S(1)), mark=lidx(S(1), 'Tomcat+Jetty 都在 classpath', 'spring-boot-starter-undertow'), done=lidx(S(1), '  Tomcat:classpath', '  Jetty:classpath', '  Tomcat → factory', '  Jetty → factory'), b=bars([['Tomcat 方案 classpath 的 jar 个数', 39, '39(18.7 MB)'], ['Jetty 方案 classpath 的 jar 个数', 77, '77(19.9 MB)'], ['Tomcat 方案里带 tomcat 的 jar', 6, '6'], ['Jetty 方案里带 jetty 的 jar', 33, '33']], 77, done=[0, 2], mark=[1, 3]), kv=KV([['Tomcat', '39 个 jar,18.7 MB,11.0.24'], ['Jetty', '77 个 jar,19.9 MB,12.1.12'], ['两个都在 classpath', '实际运行的是 Jetty'], ['Undertow', 'Central 上最新 4.0.0-M1,4.0.8 没有']], ['两个都在 classpath'])),
    step("启动与内存(各 7 次取中位数)。Tomcat:端口可连接中位 805 ms(范围 767 到 859),第 1 次请求 35.9 ms,第 2 次 1.4 ms,常驻内存启动后 163 MB、请求 2 次后 169 MB。Jetty:中位 860 ms(范围 840 到 900),第 1 次请求 47.0 ms,第 2 次 1.4 ms,常驻内存 170 MB、请求后 174 MB。Jetty 启动慢约 55 ms(算出来的差),第 1 次请求慢约 11 ms,内存多几 MB——差别都在几十毫秒、几个 MB,而且范围有一点重叠,不要把它当成选型理由。", t=tl(S(2)), mark=lidx(S(2), '  Jetty:端口可连接'), done=lidx(S(2), '  Tomcat:端口可连接'), b=bars([['Tomcat 端口可连接 ms', 805, '805'], ['Jetty 端口可连接 ms', 860, '860'], ['Tomcat 第 1 次请求 ms', 36, '35.9'], ['Jetty 第 1 次请求 ms', 47, '47.0']], 860, done=[0, 2], mark=[1, 3]), kv=KV([['启动', 'Tomcat 805 ms,Jetty 860 ms'], ['第 1 次请求', '35.9 ms 对 47.0 ms'], ['内存', '163 MB 对 170 MB(启动后)'], ['结论', '差别小,范围略有重叠']], ['结论'])),
    step("吞吐。压测端是 JDK HttpClient + 虚拟线程,每个组合 2 轮,容器线程池用默认值。快接口 /fast:并发 64 和 256 下,Tomcat 平台线程在 65978 到 71894 请求/秒之间、Jetty 在 63813 到 70616 之间,两者在同一量级;换成虚拟线程后 Tomcat 在 66429 到 70483 之间、Jetty 在 69378 到 77604 之间;p99 都在 1.9 到 8.2 ms。真正拉开差距的是会阻塞的接口 /slow50(sleep 50 ms,并发 400):Tomcat 平台线程 3681 / 3689 请求/秒,p50 110.4 ms,p99 120.9 ms;Jetty 平台线程 3568 / 3544,p50 58.3 ms 但 p99 375.2 ms——默认都是 200 个线程,吞吐接近,但延迟的形状不同:Tomcat 的请求几乎一样慢,Jetty 的中位数低、尾部很长(我没有追究原因)。Tomcat + 虚拟线程 6467 / 6478;Jetty + 虚拟线程 却只有 3519 / 3579,p50 116.2 ms,和平台线程差不多。把 server.jetty.threads.max 调到 1000 之后,Jetty 平台线程是 7309 / 7326,Jetty 虚拟线程是 6600 / 6502;对照 Tomcat 平台线程 + server.tomcat.threads.max=1000 是 7295 / 7308。也就是说在 Jetty 上打开虚拟线程不够,还要把线程池上限调大;Tomcat 开了虚拟线程就不再被 200 的上限卡住。", t=tl(S(3)), mark=lidx(S(3), '  -- Jetty + spring.threads.virtual.enabled=true', '  -- Jetty 平台线程:'), done=lidx(S(3), '  -- Tomcat 平台线程:', '  -- Tomcat + spring.threads.virtual.enabled=true', 'server.jetty.threads.max=1000', 'server.tomcat.threads.max=1000'), b=bars([['Tomcat 平台线程 /slow50 请求/秒', 3681, '3681'], ['Jetty 平台线程 /slow50', 3568, '3568'], ['Tomcat + 虚拟线程 /slow50', 6467, '6467'], ['Jetty + 虚拟线程 /slow50', 3519, '3519'], ['Jetty + 虚拟线程 + threads.max=1000', 6600, '6600'], ['Tomcat 平台线程 + threads.max=1000', 7295, '7295']], 7295, done=[2, 4, 5], mark=[3], cur=[0, 1]), kv=KV([['/fast', '两者同一量级,p99 都在 1.9 到 8.2 ms'], ['/slow50 默认 200 线程', 'Tomcat 3681,Jetty 3568;Jetty p99 375.2 ms'], ['虚拟线程', 'Tomcat 6467;Jetty 3519(要再调大 threads.max)'], ['threads.max=1000', 'Jetty 7309、Tomcat 7295']], ['虚拟线程'])),
    step("同样的请求,两个容器的反应。请求头 X-Big:4000、7000、8000 字节两者都是 200;9000 字节 Tomcat 返回 400,Jetty 返回 431 Request Header Fields Too Large;70000 字节同样。加上 server.max-http-request-header-size=16KB 后 9000 和 15000 字节都是 200;20000 字节又是 Tomcat 400、Jetty 431。路径写法(原样发送):/echo/a%2Fb 两者都 400;/echo/a//b Tomcat 200(servletPath 被规整为 /echo/a/b),Jetty 400;/echo/%2e%2e/b Tomcat 200(servletPath=/b),Jetty 400;/echo/a/./b、/echo/a/../b、/echo/a;x=1/b 两者都是 200;/echo/a%00b、/echo/a%5Cb、/echo/a\\b 两者都是 400。同一个请求落到两个容器上结果不一样,换容器时要重新过一遍这些边界。默认的空闲连接超时:Tomcat 60.1 秒后关闭,Jetty 30.0 秒后关闭。", t=tl(S(4)), mark=lidx(S(4), 'X-Big 9000 字节', 'GET /echo/a//b', 'GET /echo/%2e%2e/b', '连接空闲多久', '    Tomcat:60.1', '    Jetty:30.0'), done=lidx(S(4), 'X-Big 4000', 'GET /echo/a/b', 'GET /echo/a%2Fb', 'GET /echo/a/./b', 'GET /echo/a/../b'), b=bars([['Tomcat 默认空闲超时(秒)', 60, '60.1'], ['Jetty 默认空闲超时(秒)', 30, '30.0'], ['9000 字节请求头 Tomcat 状态码', 400, '400'], ['9000 字节请求头 Jetty 状态码', 431, '431']], 431, done=[], mark=[0, 1, 2, 3]), kv=KV([['超大请求头', 'Tomcat 400,Jetty 431'], ['//、%2e%2e', 'Tomcat 接受,Jetty 400'], ['%2F、%00、%5C', '两者都 400'], ['空闲连接', 'Tomcat 60 秒,Jetty 30 秒']], ['//、%2e%2e'])),
]
A = mkartx('x75', 75, 'Spring,Boot,Tomcat,Jetty,Undertow,内嵌容器,真实验证,动画演示',
    '同一份 Spring Boot 4.0.8 webmvc 应用换内嵌容器:Tomcat 与 Jetty 的启动、内存和快接口吞吐相差不大;两个 starter 同时在 classpath 时跑的是 Jetty;阻塞接口在默认 200 线程下 Tomcat 与 Jetty 都约 3600 请求/秒,打开虚拟线程后 Tomcat 到 6467 而 Jetty 要再调大 threads.max;请求头超限、// 与 %2e%2e 的路径、空闲连接超时两个容器反应不同;Boot 4.0.8 已经没有 Undertow。',
    '该选 Tomcat 还是 Jetty?Undertow 还能用吗?两个都在 classpath 上谁赢?虚拟线程在两个容器上效果一样吗?同样的畸形请求两个容器怎么回应?这篇用同一份代码只换 classpath 上的容器,逐项实测。',
    [('Jetty', 'Tomcat 与 Jetty 的 starter 同时在 classpath 上,实际运行的是 Jetty'), ('6467 vs 3519', '开了虚拟线程的阻塞接口:Tomcat 6467 请求/秒,Jetty 默认线程池上限下只有 3519'), ('60.1 秒 vs 30.0 秒', '默认配置下服务端关闭空闲连接的时间,Tomcat 与 Jetty')],
    [('classpath 与 Undertow', '<p>Tomcat 方案 39 个 jar,Jetty 方案 77 个 jar;两个 starter 同时在时跑的是 Jetty;Undertow 在 Boot 4.0.8 里已经没有 starter。</p>'),
     ('启动与内存', '<p>两者相差几十毫秒、几个 MB,范围略有重叠。</p>'),
     ('吞吐与虚拟线程', '<p>快接口两者同一量级;阻塞接口取决于线程池上限,Jetty 开虚拟线程之后还要调大 server.jetty.threads.max。</p>'),
     ('边界行为', '<p>超大请求头 400 与 431、// 与 %2e%2e 的路径、空闲连接超时 60 秒与 30 秒,两个容器都不一样。</p>')],
    steps,
    [ENV_X + '。同一份应用代码(spring-boot-starter-webmvc,一个 RestController),只换 classpath;Jetty 方案是把 spring-boot-starter-jetty 的依赖解析出来,再从 classpath 里去掉 tomcat-embed、spring-boot-tomcat、spring-boot-starter-tomcat 的 jar;压测端是 JDK HttpClient + 虚拟线程,与被测应用在同一台机器上,每个组合 2 轮,所以绝对数值只能在表内比较;Maven Central 的查询是用 maven-metadata.xml 和直接请求 4.0.8 的 pom',
     '没有验证:HTTP/2、TLS、压缩、WebSocket 在两个容器上的差别;长时间运行的内存与 GC;更大的并发度和更大的响应体;请求头 400 与 431 的差别背后各自是什么配置项(只观察到结果);Jetty 虚拟线程为什么在默认线程池上限下被卡住(只观察到加大 threads.max 之后恢复,没有读源码);Undertow 在其他 Boot 版本里的表现;Tomcat 的 keep-alive 超时与 Jetty 的 idle timeout 是不是同一种含义(这里只测了「发一个请求后空闲多久被服务端关闭」)'],
    '内嵌容器')
